mapper.select:
SELECT COUNT(*)
  FROM SZX1GR
 WHERE CORP_GR = #{corpGr}
   AND GR_CD   = #{grCd}
   AND SEBU_CD = #{sebuCd}

mapper.insert:
INSERT INTO SZX1GR (
    CORP_GR
  , GR_CD
  , SEBU_CD
  , SEBU_CD_NM
  , SEBU_CD_EFNM
) VALUES (
    #{corpGr}
  , NVL(#{grCd}, 'PP')
  , #{trCoCd}
  , #{susuTrCoCd, jdbcType=VARCHAR}
  , #{susuTrCoCd1, jdbcType=VARCHAR}
)

mapper.update:
UPDATE SZX1GR
   SET SEBU_CD_NM   = #{susuTrCoCd, jdbcType=VARCHAR}
     , SEBU_CD_EFNM = #{susuTrCoCd1, jdbcType=VARCHAR}
 WHERE CORP_GR      = #{corpGr}
   AND GR_CD        = NVL(#{grCd}, 'PP')
   AND SEBU_CD      = #{trCoCd}

mapper.delete:
DELETE FROM SZX1GR
 WHERE CORP_GR = #{corpGr}
   AND GR_CD   = NVL(#{grCd}, 'PP')
   AND SEBU_CD = #{trCoCd}
